From 0893d3de16a053d5f218b37a53a0087557b94371 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:23:30 +0100
Subject: [PATCH] applets/grouping: show contents in a popup when in a panel

In a panel the grouping widget squeezed its tab bar and all its widgets
into the panel's thickness, which left them unusable. It now shows its
icon there and opens the tabs in a popup, like other panel applets.

BUG: 412752
---
 applets/grouping/qml/main.qml | 144 +++++++++++++++++++++++++++-------
 1 file changed, 117 insertions(+), 27 deletions(-)

diff --git a/applets/grouping/qml/main.qml b/applets/grouping/qml/main.qml
index 59b1bf51e..e1fde054b 100644
--- a/applets/grouping/qml/main.qml
+++ b/applets/grouping/qml/main.qml
@@ -10,17 +10,21 @@ import QtQuick.Layouts

 import org.kde.kirigami as Kirigami
 import org.kde.plasma.components as PlasmaComponents
+import org.kde.plasma.core as PlasmaCore
 import org.kde.plasma.plasmoid
 import org.kde.draganddrop as DnD

 ContainmentItem {
     id: root

-    //be at least the same size as the system tray popup
-    Layout.minimumWidth: Kirigami.Units.gridUnit * 24
-    Layout.minimumHeight: Kirigami.Units.gridUnit * 21
-    Layout.preferredWidth: Layout.minimumWidth
-    Layout.preferredHeight: Layout.minimumHeight * 1.5
+    readonly property bool inPanel: Plasmoid.formFactor === PlasmaCore.Types.Horizontal
+        || Plasmoid.formFactor === PlasmaCore.Types.Vertical
+    property bool popupExpanded: false
+
+    Layout.minimumWidth: inPanel ? (Plasmoid.formFactor === PlasmaCore.Types.Horizontal ? height : 0) : content.Layout.minimumWidth
+    Layout.minimumHeight: inPanel ? (Plasmoid.formFactor === PlasmaCore.Types.Vertical ? width : 0) : content.Layout.minimumHeight
+    Layout.preferredWidth: inPanel ? Layout.minimumWidth : content.Layout.preferredWidth
+    Layout.preferredHeight: inPanel ? Layout.minimumHeight : content.Layout.preferredHeight

     property Component plasmoidItemComponent

@@ -65,8 +69,94 @@ ContainmentItem {
         }
     }

+    PlasmaCore.ToolTipArea {
+        anchors.fill: parent
+        visible: root.inPanel
+        mainText: Plasmoid.title
+        location: Plasmoid.location
+        active: !root.popupExpanded
+
+        Kirigami.Icon {
+            anchors.fill: parent
+            source: Plasmoid.icon
+            active: compactMouseArea.containsMouse
+        }
+
+        MouseArea {
+            id: compactMouseArea
+
+            property bool wasExpanded: false
+
+            anchors.fill: parent
+            hoverEnabled: true
+            onPressed: wasExpanded = root.popupExpanded
+            onClicked: root.popupExpanded = !wasExpanded
+        }
+    }
+
+    Connections {
+        target: Plasmoid
+        function onActivated() {
+            root.popupExpanded = !root.popupExpanded;
+        }
+    }
+
+    Timer {
+        id: expandedSync
+        interval: 100
+        onTriggered: root.popupExpanded = popup.visible
+    }
+
+    PlasmaCore.AppletPopup {
+        id: popup
+        visualParent: root
+        appletInterface: root
+        popupDirection: switch (Plasmoid.location) {
+            case PlasmaCore.Types.TopEdge:
+                return Qt.BottomEdge
+            case PlasmaCore.Types.LeftEdge:
+                return Qt.RightEdge
+            case PlasmaCore.Types.RightEdge:
+                return Qt.LeftEdge
+            default:
+                return Qt.TopEdge
+        }
+        margin: (Plasmoid.containmentDisplayHints & PlasmaCore.Types.ContainmentPrefersFloatingApplets) ? Kirigami.Units.largeSpacing : 0
+        removeBorderStrategy: PlasmaCore.AppletPopup.AtScreenEdges | PlasmaCore.AppletPopup.AtPanelEdges
+        hideOnWindowDeactivate: root.hideOnWindowDeactivate
+        visible: root.inPanel && root.popupExpanded
+
+        onVisibleChanged: {
+            if (!visible) {
+                expandedSync.restart();
+            } else {
+                popup.requestActivate();
+            }
+        }
+
+        mainItem: Item {
+            id: popupContent
+            Layout.minimumWidth: content.Layout.minimumWidth
+            Layout.minimumHeight: content.Layout.minimumHeight
+            Layout.preferredWidth: content.Layout.preferredWidth
+            Layout.preferredHeight: content.Layout.preferredHeight
+
+            Keys.onEscapePressed: root.popupExpanded = false
+        }
+    }
+
     Item {
+        id: content
+
+        parent: root.inPanel ? popupContent : root
         anchors.fill: parent
+
+        //be at least the same size as the system tray popup
+        Layout.minimumWidth: Kirigami.Units.gridUnit * 24
+        Layout.minimumHeight: Kirigami.Units.gridUnit * 21
+        Layout.preferredWidth: Layout.minimumWidth
+        Layout.preferredHeight: Layout.minimumHeight * 1.5
+
         PlasmaComponents.TabBar {
             id: tabbar
             anchors.top: parent.top
@@ -115,36 +205,36 @@ ContainmentItem {
             horizontalAlignment: Text.AlignHCenter
             verticalAlignment: Text.AlignVCenter
         }
-    }

-    DnD.DropArea {
-        anchors.fill: parent
+        DnD.DropArea {
+            anchors.fill: parent

-        preventStealing: true
+            preventStealing: true

-        /** Extracts the name of the applet in the drag data if present
-         * otherwise returns null*/
-        function appletName(event) {
-            if (event.mimeData.formats.indexOf("text/x-plasmoidservicename") < 0) {
-                return null;
+            /** Extracts the name of the applet in the drag data if present
+             * otherwise returns null*/
+            function appletName(event) {
+                if (event.mimeData.formats.indexOf("text/x-plasmoidservicename") < 0) {
+                    return null;
+                }
+                var plasmoidId = event.mimeData.getDataAsByteArray("text/x-plasmoidservicename");
+                return plasmoidId;
             }
-            var plasmoidId = event.mimeData.getDataAsByteArray("text/x-plasmoidservicename");
-            return plasmoidId;
-        }

-        onDragEnter: event => {
-            if (!appletName(event)) {
-                event.ignore();
+            onDragEnter: event => {
+                if (!appletName(event)) {
+                    event.ignore();
+                }
             }
-        }

-        onDrop: event => {
-            var plasmoidId = appletName(event);
-            if (!plasmoidId) {
-                event.ignore();
-                return;
+            onDrop: event => {
+                var plasmoidId = appletName(event);
+                if (!plasmoidId) {
+                    event.ignore();
+                    return;
+                }
+                Plasmoid.newTask(plasmoidId);
             }
-            Plasmoid.newTask(plasmoidId);
         }
     }
 }
-- 
2.53.0
